def prose(text):
    blocks=[]
    for p in text.split('\n\n'):
        p=p.strip()
        if not p: continue
        lines=p.splitlines()
        if len(lines)==1 and len(p)<28: blocks.append('<h4>'+html.escape(p)+'</h4>')
        else: blocks.append('<p>'+html.escape(p).replace('\n','<br>')+'</p>')
    return ''.join(blocks)
